const fs=require('fs');let pw;try{pw=require('playwright')}catch(e){pw=require(process.env.PW)}
(async()=>{const S=process.argv[2],file='file://'+process.argv[3];
const seed=fs.readFileSync(S+'/seed.js','utf8');
const b=await pw.chromium.launch();
const ctx=await b.newContext({viewport:{width:375,height:780},deviceScaleFactor:2,hasTouch:true});
const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(String(e)));p.on('console',m=>m.type()==='error'&&errs.push(m.text()));
await p.goto(file);await p.evaluate(seed).catch(()=>{});await p.waitForLoadState('load');await p.waitForTimeout(600);
await p.click('.tab[data-view=stats]');await p.waitForTimeout(300);await p.screenshot({path:S+'/p-stats.png',fullPage:true});
await p.click('.tab[data-view=today]');
// tick a habit
const before=await p.textContent('.ring-c');await p.click('[data-check=c]');await p.waitForTimeout(200);await p.screenshot({path:S+'/p-tick.png'});
console.log('ring',before,'->',await p.textContent('.ring-c'),'| meta:',await p.textContent('.habit:nth-child(3) .h-meta'));
await p.click('[data-check=e]');await p.waitForTimeout(900);console.log('all done hero:',await p.textContent('.hero h2'),'| toast:',await p.textContent('#toast'));
await p.screenshot({path:S+'/p-alldone.png'});
// past day
await p.click('.day:nth-child(2)');console.log('past day head:',await p.textContent('.col-today .sec-head'));
await p.click('.linkbtn');
// add
await p.click('.fab');await p.waitForTimeout(500);await p.screenshot({path:S+'/p-sheet.png'});
await p.click('#saveBtn');console.log('err:',await p.textContent('#fErr'));
await p.fill('#fName','Call <mum> & stretch for a really long while ok');await p.click('#iconPick label:nth-child(8)');await p.click('#saveBtn');await p.waitForTimeout(300);
console.log('habits:',await p.$$eval('.h-name',n=>n.map(x=>x.textContent)));
await p.reload();await p.waitForTimeout(400);console.log('after reload:',(await p.$$('.habit')).length,'done',await p.textContent('.count'));
// edit + delete
await p.click('.habit:last-child .more');await p.waitForTimeout(400);await p.screenshot({path:S+'/p-edit.png'});
await p.click('#delBtn');await p.click('#delBtn');await p.waitForTimeout(300);console.log('after delete:',(await p.$$('.habit')).length);
console.log('scrollW',await p.evaluate(()=>document.documentElement.scrollWidth),'errors',errs);
await b.close()})();
EOF
